INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES
(40565, 0, 0, 0, 0, 0, 0, 0, 0, 'Without you, we would still be in the dark. Who knows? Maybe you stopped another war between the Horde and the Alliance.$B$BYou are a hero of Theramore, for all of the work you have done to ease these tensions and solve this mystery. For this, I would like you to take one of these weapons from my personal armory.$B$BConcerning the Vengeful Mariner: Sailors coming to Theramore have reported seeing a shadowy figure stalking the coast. A question does remain: why was this figure so important to the deserters?$B$BI would not lose sleep. This is not a mystery for us to worry about, or another investigation to be launched. Let them keep their mariner in whatever grave he occupies.', 0),
(40687, 0, 0, 0, 0, 0, 0, 0, 0, 'You have done well, their actions could have cause chaos for us should their plots and ploys come to fruition. Take these coins, as thanks for us here in Theramore.', 0),
(40688, 0, 0, 0, 0, 0, 0, 0, 0, 'You have done well, their actions could have sown chaos in the region. Here, take these coins as thanks from us here in Theramore.', 0),
(40722, 0, 0, 0, 0, 0, 0, 0, 0, 'I wish I could have joined you on the battlefield. It must\'ve been a glorious sight.$B$BI am proud of you, and of Kagoro. You really proved yourselves for the Horde this day. The justice was served, deserters will no longer steal our supplies and war with the Alliance was avoided. It feels like there are only winners.$B$BWell, maybe except the Hyals. Poor family.$B$BAs a reward, please, take any one of these weapons. They are sacred to Brackenwall, and deserving of one such as yourself.', 0),
(40723, 0, 0, 0, 0, 0, 0, 0, 0, 'This is..$B$BI...$B$B<Falgran Hastil clears his throat, and nods his head.>$B$BThe Alliance thanks you for this action, friend.', 0),
(41324, 0, 0, 0, 0, 0, 0, 0, 0, 'Master Akh Z\'ador sends you?! What a relief! Me and the tribe were worried sick, and had already feared the worst. Losing a close friend, trusted leader and masterful riftwalker like himself would\'ve been too much for any of us to bear.', 0),
(41325, 0, 0, 0, 0, 0, 0, 0, 0, 'A shadowed specter? And it spoke of the enslavement of the Sanv tribe and Akh Z\'ador?! This is grim news, $R. For all our sakes, let me be wrong, but I fear the Harborage is in danger, grave danger!', 0),
(41326, 0, 0, 0, 0, 0, 0, 0, 0, 'I am devastated. Not even in the wildest of dreams could I have imagined this to happen. Sanv Tas\'dal, once my mentor as chieftain and noble leader of our tribe, succumbing to the sweet lies of the Burning Legion. If it wasn\'t for you and Akh Z\'ador, then my people and I would have followed him back to Draenor, to live the rest of our lives as drones for the Legion\'s machinations.$B$BThe Harborage is forever in your debt. Words cannot express how heavy my gratitude towards your selflessness lies, so please: Take this symbol of appreciation from all draenei of this humble sanctuary.', 0),
(41327, 0, 0, 0, 0, 0, 0, 0, 0, '$N, I thank you from the bottom of my heart for all you have done for the Harborage. Kas\'tal managed to contact me just in time. Any later and I fear for what might\'ve happened. Now, to what I wanted to talk with you about…$B$B<Akh Z\'ador presents a flawlessly round and shimmering teal crystal to you unlike anything you\'ve seen before.>$B$BWhat you see here is a pure draenethyst gemstone, one of the most rare commodities my people valued back on Draenor. Its status is akin to myth, although they are not the fairytale one might assume. Althoug it is just a theory, I assume this one was created between the clash of Tas\'dal\'s and my own rift magic. I want you to have it, as thanks - but also as a promise. The draenei of the Harborage will aid you if needed, for without you, we\'d be no more. Enkil Toralar, friend, and may the winds of the Twisting Nether be in your favor.', 0),
(41328, 0, 0, 0, 0, 0, 0, 0, 0, 'An exhausting process, but here it is; another pure gemstone. Please, take good care of it.', 0),
(41935, 0, 0, 0, 0, 0, 0, 0, 0, '<With the essences at hand, you read the runes out aloud. Benevolent rays of warmth encompass the spirit of Azuregos, before his corporeal body begins manifesting on the leaf laced ground. After finishing the incantation, the mighty dragon bellows a mighty roar.>$B$BWhat a gullible fool you are. Did you really expect me to hand a mere mortal the powerful treasures of my flight? Ridiculous! My treasures are mine and mine alone. As reward for your naivete, let me demonstrate how hospitable the Blue Dragonflight can be!', 0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES
(40565, 0, 0, 'Have you found Sellick Voss?', 0),
(40687, 0, 0, 'Have you find the hideout, and dispatched the turncoats?', 0),
(40688, 0, 0, 'Each day the Blackhorn are left to their devices is another day more of our patrols may be ambushed.', 0),
(40722, 0, 0, 'Have you had any luck $N?', 0),
(40723, 0, 0, 'Yes?', 0),
(41325, 0, 0, 'Proceed with caution. We do not know what otherworldly horror might await us.', 0),
(41326, 0, 0, '$N, you are restless. Tell me, could you find Akh Z\'ador?', 0),
(41328, 0, 0, 'I\'ll be here whenever you need me.', 0),
(41935, 0, 0, 'What is it, mortal? What desire drives you to pester me in my ghostly state, peacefully roaming these lands? Spare it, I know the answer already; riches and baubles are the fool’s only errand. You are too late then, I can and will not assist you in your absurd quest for treasure. How is a ghost supposed to do that, idiot?$B$B<You tell the dragon spirit about the relic you possess.>$B$BOh, a relic of resurrection, you say? Perhaps you aren’t such a simpleton after all. Listen carefully, mortal! I won’t repeat myself twice. I am offering you a deal: Resurrect me with that artifact and the riches you so desperately seek shall be yours. Gather the essence of my lesser brethren, the greater good demands their noble sacrifice. It may be grand, but it is a sacrifice I am willing to make. Only then will you be able to invoke the scroll’s latent power.', 0);
