INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(60941, 0, 0, 'Theramore was weak, to side with the Horde is betrayal after all who died! We will not be stopped so easily, the Vengeful Mariner will not forget!', 12, 0, 100, 0, 0, 0, 0, 0, 'Sellick Voss - Turtle text 66458'),
(60727, 200, 0, 'You have kept Theramore safe, may honor follow you.', 12, 0, 100, 0, 0, 0, 0, 0, 'Colonel Breen - Turtle text 66477'),
(5088, 200, 0, 'You have brought peace to these lands, on behalf of all living souls in Theramore, we thank you, for putting your own lives at risk, to put an end to this crime.', 12, 0, 100, 0, 0, 0, 0, 0, 'Falgran Hastil - Turtle text 66165'),
(61984, 0, 0, 'The Sanv will be united once more, under our almighty new shepherds!', 12, 0, 100, 0, 0, 0, 0, 0, 'Fading Apparition - Turtle text 30183'),
(91781, 200, 0, 'I do not understand, what do you...?', 12, 0, 100, 0, 0, 0, 0, 0, 'Sanv K\'la - Turtle text 30197'),
(60421, 200, 0, 'They have returned! Run for your lives!', 12, 0, 100, 0, 0, 0, 0, 0, 'Draenei Exile - Turtle text 30208'),
(60422, 200, 0, 'They have returned! Run for your lives!', 12, 0, 100, 0, 0, 0, 0, 0, 'Draenei Exile - Turtle text 30208'),
(60423, 200, 0, 'They have returned! Run for your lives!', 12, 0, 100, 0, 0, 0, 0, 0, 'Draenei Exile - Turtle text 30208'),
(60424, 200, 0, 'They have returned! Run for your lives!', 12, 0, 100, 0, 0, 0, 0, 0, 'Draenei Exile - Turtle text 30208'),
(11198, 200, 0, 'They have returned! Run for your lives!', 12, 0, 100, 0, 0, 0, 0, 0, 'Draenei Exile - Turtle text 30208'),
(61985, 0, 0, 'Sanv K\'la. After years of searching for you and the other lost sheep of mine, you finally reveal yourself.', 12, 0, 100, 0, 0, 0, 0, 0, 'Sanv Tas\'dal - Turtle text 30198'),
(61985, 1, 0, 'Your need for pitiful hiding is over, my brethren. For I have secured us a safe haven in our homeworld, the place you should all return to.', 12, 0, 100, 0, 0, 0, 0, 0, 'Sanv Tas\'dal - Turtle text 30199'),
(61985, 2, 0, 'Join me, as I can give you whatever you desire. Yet, most importantly, I can give you a purpose; a purpose greater than anything you could possibly fathom!', 12, 0, 100, 0, 0, 0, 0, 0, 'Sanv Tas\'dal - Turtle text 30200'),
(61985, 3, 0, 'Anyone eager to follow me back into the fulfilling embrace of our saviors, come forth! And those who wish to defy me...', 12, 0, 100, 0, 0, 0, 0, 0, 'Sanv Tas\'dal - Turtle text 30201'),
(61985, 4, 0, 'Prepare to be cast into the endless oblivion of the Twisting Nether!', 12, 0, 100, 0, 0, 0, 0, 0, 'Sanv Tas\'dal - Turtle text 30202'),
(61985, 5, 0, 'You feeble races. Your defiance is laughable in the face of certain death. Perish, and let your bodies pave the way for the enlightened!', 14, 0, 100, 0, 0, 0, 0, 0, 'Sanv Tas\'dal - Turtle text 30203'),
(61985, 6, 0, 'Impertinant fool! Your pathetic display of magic won\'t change a thing! Your fate is already sealed!', 14, 0, 100, 0, 0, 0, 0, 0, 'Sanv Tas\'dal - Turtle text 30205'),
(61985, 7, 0, 'No! This will not be the end, there is nowhere to hide for you anymore!', 14, 0, 100, 0, 0, 0, 0, 0, 'Sanv Tas\'dal - Turtle text 30206'),
(91782, 200, 0, 'Friends of the Harborage! Stay vigilant! Assist me in banishing this foul specter from our new home. The corrupt and demonic have to place here!', 14, 0, 100, 0, 0, 0, 0, 0, 'Akh Z\'ador - Turtle text 30204'),
(91782, 201, 0, 'The evil shadow of my former master is cast into the void again. Friends, speak with Sanv K\'la, while I regain my strength.', 14, 0, 100, 0, 0, 0, 0, 0, 'Akh Z\'ador - Turtle text 30207');
